; loops.asm -- chapter 11: DJNZ counted and timed
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "loops.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
turns   EQU RAM_START          ; 3 counts of two bytes
; How many turns DJNZ makes from B = 0, 1 and 255; the time of a loop of one
; NOP from B = 1, 10 and 0; and the time of a loop that counts 1000 in BC,
; the way chapter 7 mended it.
init:   di
        ld sp, SYS_AREA
        ld b, 0
        ld hl, 0
k0:     inc hl                  ; one more turn
        djnz k0
        ld (turns + 0), hl      ; how many turns B = 0 made
        ld b, 1
        ld hl, 0
k1:     inc hl                  ; one more turn
        djnz k1
        ld (turns + 2), hl      ; how many turns B = 1 made
        ld b, 255
        ld hl, 0
k2:     inc hl                  ; one more turn
        djnz k2
        ld (turns + 4), hl      ; how many turns B = 255 made
d0:     ld b, 1
e0:     nop                     ; the body of the loop
        djnz e0
f0:     nop
d1:     ld b, 10
e1:     nop                     ; the body of the loop
        djnz e1
f1:     nop
d2:     ld b, 0
e2:     nop                     ; the body of the loop
        djnz e2
f2:     nop
g0:     ld bc, 1000
g1:     dec bc
        ld a, b
        or c                    ; Z only when B and C are both 0
        jr nz, g1
g2:     nop
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
